<?php
namespace App\Services\Procurement;
use App\Models\{InventoryBatch,InventoryItem,InventoryStock,StockMovement,Store};use Illuminate\Support\Facades\DB;use RuntimeException;
class StoreStockService{
 public function balance(Store $store,InventoryItem $item):InventoryStock{return InventoryStock::firstOrCreate(['property_id'=>$store->property_id,'store_id'=>$store->id,'inventory_item_id'=>$item->id],['quantity'=>0,'reserved_quantity'=>0]);}
 public function move(Store $store,InventoryItem $item,float $quantity,string $type,?int $userId=null,?string $notes=null,?object $source=null,?Store $counterStore=null,?string $reference=null,float $unitCost=0):StockMovement{return DB::transaction(function()use($store,$item,$quantity,$type,$userId,$notes,$source,$counterStore,$reference,$unitCost){$stock=InventoryStock::query()->where('store_id',$store->id)->where('inventory_item_id',$item->id)->lockForUpdate()->first();if(!$stock)$stock=InventoryStock::create(['property_id'=>$store->property_id,'store_id'=>$store->id,'inventory_item_id'=>$item->id,'quantity'=>0]);$new=(float)$stock->quantity+$quantity;if($new<0)throw new RuntimeException("Insufficient {$item->name} stock in {$store->name}.");$stock->update(['quantity'=>$new]);$item=InventoryItem::query()->lockForUpdate()->findOrFail($item->id);$total=(float)$item->quantity_on_hand+$quantity;if($total<0)throw new RuntimeException("Insufficient total stock for {$item->name}.");$update=['quantity_on_hand'=>$total];if($quantity>0&&$unitCost>0){$oldQty=max(0,(float)$item->quantity_on_hand);$update['average_cost']=($oldQty+$quantity)>0?(($oldQty*(float)$item->average_cost)+($quantity*$unitCost))/($oldQty+$quantity):$unitCost;}$item->update($update);return StockMovement::create(['property_id'=>$store->property_id,'store_id'=>$store->id,'counter_store_id'=>$counterStore?->id,'inventory_item_id'=>$item->id,'type'=>$type,'quantity'=>$quantity,'unit_cost'=>$unitCost?:$item->average_cost,'balance_after'=>$total,'source_type'=>$source?get_class($source):null,'source_id'=>$source?->id,'reference'=>$reference,'notes'=>$notes,'created_by'=>$userId]);});}
 public function transfer(Store $from,Store $to,InventoryItem $item,float $quantity,?int $userId=null,?object $source=null,?string $reference=null):void{DB::transaction(function()use($from,$to,$item,$quantity,$userId,$source,$reference){$this->move($from,$item,-$quantity,'transfer_out',$userId,"Transfer to {$to->name}",$source,$to,$reference);$this->move($to,$item,$quantity,'transfer_in',$userId,"Transfer from {$from->name}",$source,$from,$reference);});}
 public function receiveBatch(Store $store,InventoryItem $item,float $qty,float $unitCost,?string $batch,mixed $expires,?int $supplierId,object $source,?int $userId,string $reference):void{$this->move($store,$item,$qty,'purchase',$userId,'Goods received',$source,null,$reference,$unitCost);if($batch||$expires){InventoryBatch::create(['property_id'=>$store->property_id,'store_id'=>$store->id,'inventory_item_id'=>$item->id,'batch_number'=>$batch?:$reference,'expires_at'=>$expires,'quantity_received'=>$qty,'quantity_remaining'=>$qty,'unit_cost'=>$unitCost,'supplier_id'=>$supplierId]);}}
}
